fn numpy_matrix_transpose(x: Vec<Vec<f32>>) -> Vec<Vec<f32>> {
    // Number of rows in the input matrix
    let rows = x.len();
    // Number of columns in the input matrix (assumes at least one row)
    let cols = x[0].len();

    // For each column index j in 0..cols, build a transposed row by
    // picking the j-th element from each original row.
    (0..cols)
        .map(|j| {
            x.iter()
                .map(|row| row[j])
                .collect::<Vec<f32>>()
        })
        .collect()
}

